// One Opus reviewer reads an edition's story page against the house rules, the data and its prologue's entries.
// args from node tools/args.cjs <topic> review [port]. Apply its findings by hand to src/story.html, topics.cjs or the prologue; then rebuild.
export const meta = {
  name: 'count-page-review',
  description: 'One reviewer checks an edition of The Count story page: the hand-written copy against the house rules and the data, the prologue\'s theses and lines against their entries, and the page\'s behavior for this edition\'s counts',
  phases: [{ title: 'Review', detail: 'one Opus reviewer in headless Chrome', model: 'opus' }],
}
const A = args
if (!A || !A.out || !A.url) throw new Error('args missing; generate them with node tools/args.cjs <topic> review [port]')
const FINDINGS = { type: 'object', properties: { findings: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string', enum: ['blocker', 'should-fix', 'nit'] }, where: { type: 'string' }, problem: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' } }, required: ['severity', 'where', 'problem', 'evidence', 'fix'] } }, summary: { type: 'string' } }, required: ['findings', 'summary'] }
phase('Review')
const r = await agent(`Review the ${A.topic} edition of a static prototype story page. The page is ${A.out}story.html (a copy of the master ${A.proto}/src/story.html; report fixes against the master, or against ${A.proto}/topics.cjs for topic-supplied copy); its data are ${A.out}ledger.json (${A.acts} acts, large: query with node -e; its "topic" block holds the edition's chapters, families, terms and copy) and ${A.out}story/prologue.json (a sourced prologue: ${A.steps} steps, ${A.outside} of them outside the count, with gaps and cautions, written by a research sweep over the Trump Tracker entries in ${A.dir}<id>.json and the ledger ${A.ledgerMd}).${A.otherEdition ? ` Another edition of the same page, at ${A.otherEdition}, has been reviewed and fixed; this edition reuses that page through the topic block, so look for what differs.` : ''} House rules: no em dashes in prose; the most precise language the evidence supports; understate; no loaded adjectives; the page carries no opinion; every factual sentence comes from the data or a computed count, and hand-written framing claims nothing beyond the data; nothing may imply that a prologue step caused an act; every count-based string must read correctly at zero and at a full span.

Check: (1) every hand-written or topic-supplied string as it renders for this edition (the hero, the intro's h-sub and its gap line, the section caves including the "limits" section's cave, the era stats and coverage lines, the thread screen, the totals, the end, the panel and the story offer sentence) for overclaims, wording that only made sense for another edition, and numbers that break at zero or a complete span; (2) the prologue outline: read every section title and thesis and at least fifteen step lines and whys against their entries or ledger bullets, including the whole last section and every step whose whyBasis is "stated", and flag any claim the entry does not make, any date that is not the event's date without a dateNote, any quote whose quoteBy is not what the source says (spot-check five), any ledger act counted twice; (3) the page's behavior for this edition's counts: the wall rows, the panel's rows and counts, the badge on every step, the intro's wording, the hero parenthetical; (4) the first chapter: its era screen, its stats (fewer than five acts means no pace stat), its walk link to focus.html, the strip's start; (5) anything that would throw at runtime for this edition.${A.focus ? ` Pay attention to ${A.focus}.` : ''} Use headless Chrome via the puppeteer in ${A.proto}/../../controversial-trump/website/node_modules against ${A.url} if it is up (start a server with python3 -m http.server ${A.port} from ${A.serveFrom} in the background if not); never open the user's visible browser pane. Report only confirmed or clearly plausible defects, with exact replacement text or code, against the master file, topics.cjs or the data file.`, { label: `review:${A.topic}-story`, phase: 'Review', schema: FINDINGS, model: 'opus', effort: 'high' })
return r
